INSERT INTO account_chart (id, "companyId", code, name, type, "parentCode", level, "isPostable", "isActive", source, "templateVersion")
SELECT
 'pgc-' || es_companies.id || '-' || pgc_accounts.code,
 es_companies.id,
 pgc_accounts.code,
 pgc_accounts.name,
 pgc_accounts.type::account_type,
 pgc_accounts.parent_code,
 pgc_accounts.level,
 pgc_accounts.is_postable,
 pgc_accounts.code IN ('129', '4100', '4300', '472', '4751', '477', '572', '600', '700'),
 'ES_PGC',
 'PGC-2024-BOE-A-2007-19884'
FROM es_companies
CROSS JOIN pgc_accounts
ON CONFLICT ("companyId", code) DO UPDATE SET
 name = EXCLUDED.name,
 type = EXCLUDED.type,
 "parentCode" = EXCLUDED."parentCode",
 level = EXCLUDED.level,
 "isPostable" = EXCLUDED."isPostable",
 source = EXCLUDED.source,
 "templateVersion" = EXCLUDED."templateVersion";
